dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "input"
    },
    {
      "parameter": "gene",
      "label": "Gene",
      "type": "input",
      "values": "kp genes"
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "input"
    }
  ],
  "sections": [
    {
      "section id": "gene_expression_tissue",
      "header": "Gene Expression for Tissue",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "gene-expression-tissue",
        "parameters": [
          "tissue"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Set Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Samples",
            "raw field": "nSamples"
          },
          {
            "type": "raw",
            "field name": "Mean TPM",
            "raw field": "meanTpm"
          }
        ],
        "top rows": [
          "Gene",
          "Mean TPM",
          "Samples",
          "Set Gene"
        ],
        "column formatting": {
          "Set Gene": {
            "type": [
              "set parameter"
            ],
            "parameter": "gene"
          }
        }
      },
      "pre filters": [
        {
          "field": "Mean TPM",
          "value": "10000,20000",
          "type": "search and"
        }
      ],
      "filters": [
        {
          "field": "Mean TPM",
          "label": "Mean TPM (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "gene_expression",
      "header": "Tissue Gene Expression for Gene",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "gene-expression",
        "parameters": [
          "gene"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Set Tissue",
            "raw field": "tissue"
          },
          {
            "type": "array to string",
            "field name": "Collection",
            "raw field": "collection",
            "separate by": ","
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Min TPM",
            "raw field": "minTpm"
          },
          {
            "type": "raw",
            "field name": "Q1 TPM",
            "raw field": "firstQuTpm"
          },
          {
            "type": "raw",
            "field name": "Mean TPM",
            "raw field": "meanTpm"
          },
          {
            "type": "raw",
            "field name": "Median TPM",
            "raw field": "medianTpm"
          },
          {
            "type": "raw",
            "field name": "Q3 TPM",
            "raw field": "thirdQuTpm"
          },
          {
            "type": "raw",
            "field name": "Max TPM",
            "raw field": "maxTpm"
          },
          {
            "type": "raw",
            "field name": "Samples",
            "raw field": "nSamples"
          },
          {
            "type": "raw",
            "field name": "tpmForAllSamples",
            "raw field": "tpmForAllSamples"
          }
        ],
        "top rows": [
          "Tissue",
          "Biosample",
          "Collection",
          "Dataset",
          "Q1 TPM",
          "Mean TPM",
          "Median TPM",
          "Q3 TPM",
          "Max TPM",
          "Samples",
          "Set Tissue"
        ],
        "column formatting": {
          "Set Tissue": {
            "type": [
              "set parameter"
            ],
            "parameter": "tissue"
          }
        }
      },
      "pre filters": [
        {
          "field": "Tissue",
          "value": "search parameter",
          "parameter": "tissue",
          "type": "search"
        }
      ],
      "filters": [
        {
          "field": "Collection",
          "label": "Collection",
          "type": "dropdown",
          "label in bubble": "true"
        },
        {
          "field": "Mean TPM",
          "label": "Mean TPM (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "gene_links",
      "header": "Gene Links",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "gene-links",
        "parameters": [
          "tissue",
          "gene"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Target Gene",
            "raw field": "targetGene"
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "Target Region",
            "fields to join": [
              "chromosome",
              "targetGeneStart",
              "targetGeneEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "array to string",
            "field name": "Assay",
            "raw field": "assay",
            "separate by": ","
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          }
        ],
        "top rows": [
          "Biosample",
          "Target Gene",
          "Target Region",
          "Method",
          "Source",
          "Dataset",
          "Assay"
        ],
        "column formatting": {
          "Set Gene": {
            "type": [
              "set parameter"
            ],
            "parameter": "gene"
          }
        }
      },
      "filters": [
        {
          "field": "Target Gene",
          "label": "Target Gene",
          "type": "dropdown",
          "label in bubble": "true"
        },
        {
          "field": "Method",
          "label": "Method",
          "type": "dropdown",
          "label in bubble": "true"
        },
        {
          "field": "Source",
          "label": "Source",
          "type": "dropdown",
          "label in bubble": "true"
        },
        {
          "field": "Assay",
          "label": "Assay",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ]
    }
  ]
}
